 private static class UnmodifiableList<T> extends AbstractList<T> implements java.io.Serializable {final List<? extends T> l;UnmodifiableList(List<? extends T> l){this.l=Objects.requireNonNull(l);}public int size(){return l.size();}public T get(int i){return l.get(i);}public T set(int i,T v){throw new UnsupportedOperationException();}public void add(int i,T v){throw new UnsupportedOperationException();}public T remove(int i){throw new UnsupportedOperationException();}public boolean addAll(Collection<? extends T> c){throw new UnsupportedOperationException();}public boolean addAll(int i,Collection<? extends T> c){throw new UnsupportedOperationException();}public boolean remove(Object o){throw new UnsupportedOperationException();}public boolean removeAll(Collection<?> c){throw new UnsupportedOperationException();}public boolean retainAll(Collection<?> c){throw new UnsupportedOperationException();}public void clear(){throw new UnsupportedOperationException();}public void replaceAll(java.util.function.UnaryOperator<T> o){throw new UnsupportedOperationException();}public void sort(Comparator<? super T> c){throw new UnsupportedOperationException();}public boolean removeIf(java.util.function.Predicate<? super T> p){throw new UnsupportedOperationException();}public List<T> subList(int f,int t){return unmodifiableList(l.subList(f,t));}}
