 public static <K,V> Map<K,V> unmodifiableMap(Map<? extends K,? extends V> m){return new UnmodifiableMap<K,V>(m);}
 private static class UnmodifiableMap<K,V> extends AbstractMap<K,V> implements java.io.Serializable {final Map<? extends K,? extends V> m;UnmodifiableMap(Map<? extends K,? extends V> m){this.m=Objects.requireNonNull(m);}public int size(){return m.size();}public boolean containsKey(Object k){return m.containsKey(k);}public V get(Object k){return m.get(k);}public V put(K k,V v){throw new UnsupportedOperationException();}public V remove(Object k){throw new UnsupportedOperationException();}public void clear(){throw new UnsupportedOperationException();}public void putAll(Map<? extends K,? extends V> x){throw new UnsupportedOperationException();}public V putIfAbsent(K k,V v){throw new UnsupportedOperationException();}public boolean remove(Object k,Object v){throw new UnsupportedOperationException();}public boolean replace(K k,V a,V b){throw new UnsupportedOperationException();}public V replace(K k,V v){throw new UnsupportedOperationException();}public void replaceAll(java.util.function.BiFunction<? super K,? super V,? extends V> f){throw new UnsupportedOperationException();}public V computeIfAbsent(K k,java.util.function.Function<? super K,? extends V> f){throw new UnsupportedOperationException();}public V computeIfPresent(K k,java.util.function.BiFunction<? super K,? super V,? extends V> f){throw new UnsupportedOperationException();}public V compute(K k,java.util.function.BiFunction<? super K,? super V,? extends V> f){throw new UnsupportedOperationException();}public V merge(K k,V v,java.util.function.BiFunction<? super V,? super V,? extends V> f){throw new UnsupportedOperationException();}public Set<K> keySet(){return unmodifiableSet(m.keySet());}public Collection<V> values(){return unmodifiableCollection(m.values());}public Set<Entry<K,V>> entrySet(){return unmodifiableSet(new AbstractSet<Entry<K,V>>(){public int size(){return m.size();}public Iterator<Entry<K,V>> iterator(){final Iterator<? extends Entry<? extends K,? extends V>> i=m.entrySet().iterator();return new Iterator<Entry<K,V>>(){public boolean hasNext(){return i.hasNext();}public Entry<K,V> next(){return new SimpleImmutableEntry<K,V>(i.next());}};}});}}
 public static <E> Set<E> newSetFromMap(Map<E,Boolean> m){if(!m.isEmpty())throw new IllegalArgumentException();return new MapSet<E>(m);}
 private static class MapSet<E> extends AbstractSet<E> implements java.io.Serializable {final Map<E,Boolean> m;MapSet(Map<E,Boolean> m){this.m=m;}public int size(){return m.size();}public boolean contains(Object x){return m.containsKey(x);}public boolean add(E x){return m.put(x,Boolean.TRUE)==null;}public boolean remove(Object x){return m.remove(x)!=null;}public void clear(){m.clear();}public Iterator<E> iterator(){return m.keySet().iterator();}}
 public static <T> Collection<T> synchronizedCollection(Collection<T> c){return new SyncCollection<T>(c);}
 private static class SyncCollection<T> implements Collection<T>,java.io.Serializable {final Collection<T> c;final Object lock;SyncCollection(Collection<T> c){this.c=Objects.requireNonNull(c);lock=this;}SyncCollection(Collection<T> c,Object l){this.c=c;lock=l;}public int size(){synchronized(lock){return c.size();}}public boolean isEmpty(){synchronized(lock){return c.isEmpty();}}public boolean contains(Object o){synchronized(lock){return c.contains(o);}}public Iterator<T> iterator(){return c.iterator();}public Object[] toArray(){synchronized(lock){return c.toArray();}}public <E>E[] toArray(E[] a){synchronized(lock){return c.toArray(a);}}public boolean add(T x){synchronized(lock){return c.add(x);}}public boolean remove(Object x){synchronized(lock){return c.remove(x);}}public boolean containsAll(Collection<?> x){synchronized(lock){return c.containsAll(x);}}public boolean addAll(Collection<? extends T> x){synchronized(lock){return c.addAll(x);}}public boolean removeAll(Collection<?> x){synchronized(lock){return c.removeAll(x);}}public boolean retainAll(Collection<?> x){synchronized(lock){return c.retainAll(x);}}public void clear(){synchronized(lock){c.clear();}}public String toString(){synchronized(lock){return c.toString();}}public boolean removeIf(java.util.function.Predicate<? super T> p){synchronized(lock){return c.removeIf(p);}}}
