 public static <T> List<T> synchronizedList(List<T> l){return l instanceof RandomAccess?new SyncRandomList<T>(l):new SyncList<T>(l);}
 private static class SyncList<T> extends SyncCollection<T> implements List<T> {final List<T> list;SyncList(List<T> l){super(l);list=l;}SyncList(List<T> l,Object lock){super(l,lock);list=l;}public T get(int i){synchronized(lock){return list.get(i);}}public T set(int i,T x){synchronized(lock){return list.set(i,x);}}public void add(int i,T x){synchronized(lock){list.add(i,x);}}public T remove(int i){synchronized(lock){return list.remove(i);}}public int indexOf(Object x){synchronized(lock){return list.indexOf(x);}}public int lastIndexOf(Object x){synchronized(lock){return list.lastIndexOf(x);}}public boolean addAll(int i,Collection<? extends T> c){synchronized(lock){return list.addAll(i,c);}}public ListIterator<T> listIterator(){return list.listIterator();}public ListIterator<T> listIterator(int i){return list.listIterator(i);}public List<T> subList(int f,int t){synchronized(lock){List<T> x=list.subList(f,t);return x instanceof RandomAccess?new SyncRandomList<T>(x,lock):new SyncList<T>(x,lock);}}public boolean equals(Object o){synchronized(lock){return o==this||list.equals(o);}}public int hashCode(){synchronized(lock){return list.hashCode();}}public void replaceAll(java.util.function.UnaryOperator<T> op){synchronized(lock){list.replaceAll(op);}}public void sort(Comparator<? super T> c){synchronized(lock){list.sort(c);}}}
